column2:
set -e
node tools/format-corpus.mjs
node tools/format-corpus.mjs --check
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const dir = 'corpus/projects/lz-roundtrip/';
for (const [name, limit] of [['main.typed', 80], ['scripts/explore.js', 80], ['project.json', 73], ['notes.md', 73]]) {
  const width = Math.max(...readFileSync(dir + name, 'utf8').split('\n').map(line => line.length));
  assert.ok(width <= limit, name);
  console.log(name, width);
}
const { focus } = JSON.parse(readFileSync(dir + 'project.json', 'utf8'));
assert.match(readFileSync(dir + 'main.typed', 'utf8').split('\n')[focus - 1], /output\.charCodeAt\(written - distance\)/);
EOF
git diff --check
